const real = $('Leer real').first().json.values;
const pru = $('Leer pruebas').first().json.values;
const norm = (s) => String(s === null || s === undefined ? '' : s).toUpperCase().replace(/[\s\-\/]/g, '');
const tokens4 = (s) => String(s === null || s === undefined ? '' : s).match(/(?<!\d)\d{4}(?!\d)/g) || [];
const celda = (v, i, j) => String(((v[i] || [])[j]) === undefined ? '' : (v[i] || [])[j]);

const bloquesReal = [];
for (let i = 0; i < real.length; i++) {
  const a = celda(real, i, 0).trim();
  const b = celda(real, i, 1).trim().toUpperCase();
  const d1 = celda(real, i, 3).trim();
  if (/^\d+$/.test(a) && a !== '0' && b !== 'CARGADOR' && d1 !== '') {
    bloquesReal.push({ fila: i + 1, d1, remolque: celda(real, i, 1).trim(), cond: tokens4(celda(real, i + 1, 3)), prop: celda(real, i + 2, 1).trim() });
  }
}
const bloquesPru = [];
for (let i = 1; i < pru.length; i += 3) {
  const d1 = celda(pru, i, 3).trim();
  bloquesPru.push({ fila: i + 1, matricula: d1.split(' // ')[0].trim(), remolque: celda(pru, i, 1).trim(), cond: tokens4(celda(pru, i + 1, 3)), prop: celda(pru, i + 2, 1).trim() });
}

const usados = new Set();
const comunes = [];
const soloPruebas = [];
for (const p of bloquesPru) {
  const r = bloquesReal.find((x, k) => !usados.has(k) && norm(x.d1).startsWith(norm(p.matricula)));
  if (r) { usados.add(bloquesReal.indexOf(r)); comunes.push({ p, r }); } else soloPruebas.push(p.matricula);
}
const soloReal = bloquesReal.filter((x, k) => !usados.has(k)).map((x) => x.d1.split('//')[0].trim());

const rem = { iguales: 0, pruebasVacio: [], realVacio: [], distintos: [] };
const con = { iguales: 0, distintos: [] };
for (const { p, r } of comunes) {
  const a = norm(p.remolque);
  const b = norm(r.remolque);
  if (a === b) rem.iguales++;
  else if (a === '') rem.pruebasVacio.push(p.matricula + ' (hoja: ' + r.remolque + ')');
  else if (b === '' || b === '#N/A') rem.realVacio.push(p.matricula + ' (T2000: ' + p.remolque + ')');
  else rem.distintos.push(p.matricula + ': hoja ' + r.remolque + ' / T2000 ' + p.remolque);
  const ca = p.cond.join(',');
  const cb = r.cond.join(',');
  if (ca === cb) con.iguales++;
  else con.distintos.push(p.matricula + ': hoja [' + cb + '] / T2000 [' + ca + ']');
}

return [{ json: {
  tractorasHoja: bloquesReal.length,
  tractorasT2000: bloquesPru.length,
  comunes: comunes.length,
  soloEnHoja: soloReal,
  soloEnT2000: soloPruebas,
  remolque: { iguales: rem.iguales, t2000SinRemolque: rem.pruebasVacio.length, hojaSinRemolque: rem.realVacio, distintos: rem.distintos, t2000SinRemolqueLista: rem.pruebasVacio },
  conductores: con,
} }];
